        input_scale = 1.0 - 0.1 * log_counts[seq] / denominator
        input_scale = input_scale.masked_fill(seq.eq(0), 0.0)
        emb = self.dropout(self.item_emb(seq) * input_scale.unsqueeze(-1))
        out, _ = self.gru(emb)"
